            if (OLD_EXIF_INTERFACE.equals(psiClass.getQualifiedName())) {
                String message = "Use `" + NEW_EXIF_INTERFACE + "` instead of `" + OLD_EXIF_INTERFACE + "`";
                context.report(ISSUE, context.getLocation(reference), message);
            }
        }
    }
}
